WHERE e.space_id = #{query.spaceId}
  AND c.started_at >= #{query.startAt}
  AND c.started_at < #{query.endAt}

  AND e.agent_id = #{query.agentId}


  AND EXISTS (
      SELECT 1
      FROM agent_execution_model_call m
      WHERE m.execution_id = e.id
        AND m.model_id = #{query.modelId}
  )


  AND e.status = #{query.executionStatus}


  AND e.execution_mode = #{query.executionMode}



    AND e.online_experiment_id IS NOT NULL
    AND e.online_experiment_id IS NULL
